import json
from offline_coordination import replication as R
from offline_coordination.replication import compare_proofs, InvalidProofError

def show(raw):
    print(raw.decode().rstrip())

# TypeError precedence: non-bytes left must win even with invalid right.
for args in ((1, b"x\n"), (b"x\n", 1), ("s", b"x\n")):
    try:
        compare_proofs(*args)
    except TypeError as e:
        print("TypeError:", e)

# Invalid either side
try:
    compare_proofs(b"bad\n", b"bad2\n")
except InvalidProofError as e:
    print("InvalidProofError:", e)

# auth-only difference between otherwise identical entries:
def proof_with_auth(start, end, auth=None):
    entries=[]
    import hashlib
    def h(s): return hashlib.sha256(s.encode()).hexdigest()
    for s in range(start,end+1):
        e={"after":h(f"a{s}"),"before":h(f"a{s-1}"),"id":f"r{s}","seq":s,"source":"n"}
        if auth: e["auth"]={"keyVersion":1,"node":"n"}
        entries.append(e)
    body={"endSeq":end,"entries":entries,"firstBefore":entries[0]["before"],
          "lastAfter":entries[-1]["after"],"startSeq":start,"version":1}
    body["digest"]=hashlib.sha256(json.dumps(body,sort_keys=True,separators=(",",":"),ensure_ascii=False).encode()).hexdigest()
    return json.dumps(body,sort_keys=True,separators=(",",":"),ensure_ascii=False).encode()+b"\n"

p1=proof_with_auth(1,3)
p2=proof_with_auth(1,3,auth=True)
show(compare_proofs(p1,p2))   # fork at 1, same before -> common seq0
show(compare_proofs(p2,p1))   # swapped: same relation/conflict/common

# disjoint with differing tags still disjoint
pa=proof_with_auth(1,2); pb=proof_with_auth(5,6,auth=True)
show(compare_proofs(pa,pb))
